INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk4-03','HSK4-03','HSK 4 · Đề 03','hsk','HSK 4',70,'published',1,'Đề luyện HSK 4 số 03 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk4-03-q01','seed-hsk4-03',1,'single_choice','Pinyin phù hợp với “管理” là phương án nào?','Pinyin của “管理” là “guǎnlǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quản lý”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q02','seed-hsk4-03',2,'single_choice','Chọn từ Hán ngữ có nghĩa “đạt được”.','Từ phù hợp là “获得”, đọc là huòdé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q03','seed-hsk4-03',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “方法 — fāngfǎ”, nghĩa là “phương pháp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q04','seed-hsk4-03',4,'single_choice','Từ “安排” gần nghĩa nhất với phương án nào?','“安排” (ānpái) có nghĩa là “sắp xếp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q05','seed-hsk4-03',5,'single_choice','Pinyin phù hợp với “成功” là phương án nào?','Pinyin của “成功” là “chénggōng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thành công”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q06','seed-hsk4-03',6,'single_choice','Chọn từ Hán ngữ có nghĩa “đề xuất”.','Từ phù hợp là “建议”, đọc là jiànyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q07','seed-hsk4-03',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “交流 — jiāoliú”, nghĩa là “giao lưu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q08','seed-hsk4-03',8,'single_choice','Từ “提供” gần nghĩa nhất với phương án nào?','“提供” (tígōng) có nghĩa là “cung cấp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q09','seed-hsk4-03',9,'single_choice','Pinyin phù hợp với “内容” là phương án nào?','Pinyin của “内容” là “nèiróng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nội dung”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q10','seed-hsk4-03',10,'single_choice','Chọn từ Hán ngữ có nghĩa “năng lực”.','Từ phù hợp là “能力”, đọc là nénglì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q11','seed-hsk4-03',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “积极 — jījí”, nghĩa là “tích cực”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-03-q12','seed-hsk4-03',12,'single_choice','Từ “失败” gần nghĩa nhất với phương án nào?','“失败” (shībài) có nghĩa là “thất bại”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
