('seed-hsk4-05-q21','seed-hsk4-05',21,'single_choice','Pinyin phù hợp với “标准” là phương án nào?','Pinyin của “标准” là “biāozhǔn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tiêu chuẩn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-05-q22','seed-hsk4-05',22,'single_choice','Chọn từ Hán ngữ có nghĩa “trách nhiệm”.','Từ phù hợp là “责任”, đọc là zérèn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
