INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk4-06','HSK4-06','HSK 4 · Đề 06','hsk','HSK 4',70,'published',1,'Đề luyện HSK 4 số 06 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk4-06-q01','seed-hsk4-06',1,'single_choice','Pinyin phù hợp với “提供” là phương án nào?','Pinyin của “提供” là “tígōng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cung cấp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q02','seed-hsk4-06',2,'single_choice','Chọn từ Hán ngữ có nghĩa “nội dung”.','Từ phù hợp là “内容”, đọc là nèiróng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q03','seed-hsk4-06',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “能力 — nénglì”, nghĩa là “năng lực”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q04','seed-hsk4-06',4,'single_choice','Từ “积极” gần nghĩa nhất với phương án nào?','“积极” (jījí) có nghĩa là “tích cực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q05','seed-hsk4-06',5,'single_choice','Pinyin phù hợp với “失败” là phương án nào?','Pinyin của “失败” là “shībài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thất bại”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q06','seed-hsk4-06',6,'single_choice','Chọn từ Hán ngữ có nghĩa “thích nghi”.','Từ phù hợp là “适应”, đọc là shìyìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q07','seed-hsk4-06',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “发展 — fāzhǎn”, nghĩa là “phát triển”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q08','seed-hsk4-06',8,'single_choice','Từ “支持” gần nghĩa nhất với phương án nào?','“支持” (zhīchí) có nghĩa là “hỗ trợ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q09','seed-hsk4-06',9,'single_choice','Pinyin phù hợp với “过程” là phương án nào?','Pinyin của “过程” là “guòchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quá trình”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q10','seed-hsk4-06',10,'single_choice','Chọn từ Hán ngữ có nghĩa “thực tế”.','Từ phù hợp là “实际”, đọc là shíjì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
