('seed-hsk4-06-q26','seed-hsk4-06',26,'single_choice','Chọn từ Hán ngữ có nghĩa “thích nghi”.','Từ phù hợp là “适应”, đọc là shìyìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q27','seed-hsk4-06',27,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “发展 — fāzhǎn”, nghĩa là “phát triển”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-06-q28','seed-hsk4-06',28,'single_choice','Từ “支持” gần nghĩa nhất với phương án nào?','“支持” (zhīchí) có nghĩa là “hỗ trợ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
