INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk4-07','HSK4-07','HSK 4 · Đề 07','hsk','HSK 4',70,'published',1,'Đề luyện HSK 4 số 07 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk4-07-q01','seed-hsk4-07',1,'single_choice','Pinyin phù hợp với “实际” là phương án nào?','Pinyin của “实际” là “shíjì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thực tế”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q02','seed-hsk4-07',2,'single_choice','Chọn từ Hán ngữ có nghĩa “thái độ”.','Từ phù hợp là “态度”, đọc là tàidù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q03','seed-hsk4-07',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “标准 — biāozhǔn”, nghĩa là “tiêu chuẩn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q04','seed-hsk4-07',4,'single_choice','Từ “责任” gần nghĩa nhất với phương án nào?','“责任” (zérèn) có nghĩa là “trách nhiệm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q05','seed-hsk4-07',5,'single_choice','Pinyin phù hợp với “管理” là phương án nào?','Pinyin của “管理” là “guǎnlǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quản lý”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q06','seed-hsk4-07',6,'single_choice','Chọn từ Hán ngữ có nghĩa “đạt được”.','Từ phù hợp là “获得”, đọc là huòdé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q07','seed-hsk4-07',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “方法 — fāngfǎ”, nghĩa là “phương pháp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q08','seed-hsk4-07',8,'single_choice','Từ “安排” gần nghĩa nhất với phương án nào?','“安排” (ānpái) có nghĩa là “sắp xếp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q09','seed-hsk4-07',9,'single_choice','Pinyin phù hợp với “成功” là phương án nào?','Pinyin của “成功” là “chénggōng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thành công”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q10','seed-hsk4-07',10,'single_choice','Chọn từ Hán ngữ có nghĩa “đề xuất”.','Từ phù hợp là “建议”, đọc là jiànyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
