('seed-hsk4-07-q31','seed-hsk4-07',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “交流 — jiāoliú”, nghĩa là “giao lưu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q32','seed-hsk4-07',32,'single_choice','Từ “提供” gần nghĩa nhất với phương án nào?','“提供” (tígōng) có nghĩa là “cung cấp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-07-q33','seed-hsk4-07',33,'single_choice','Pinyin phù hợp với “内容” là phương án nào?','Pinyin của “内容” là “nèiróng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nội dung”.',NULL,NULL,0,1,'',datetime('now')),
