('seed-hsk4-08-q36','seed-hsk4-08',36,'single_choice','Từ “管理” gần nghĩa nhất với phương án nào?','“管理” (guǎnlǐ) có nghĩa là “quản lý”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-08-q37','seed-hsk4-08',37,'single_choice','Pinyin phù hợp với “获得” là phương án nào?','Pinyin của “获得” là “huòdé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đạt được”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-08-q38','seed-hsk4-08',38,'single_choice','Chọn từ Hán ngữ có nghĩa “phương pháp”.','Từ phù hợp là “方法”, đọc là fāngfǎ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-08-q39','seed-hsk4-08',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “安排 — ānpái”, nghĩa là “sắp xếp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-08-q40','seed-hsk4-08',40,'single_choice','Từ “成功” gần nghĩa nhất với phương án nào?','“成功” (chénggōng) có nghĩa là “thành công”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-08-q41','seed-hsk4-08',41,'single_choice','Pinyin phù hợp với “建议” là phương án nào?','Pinyin của “建议” là “jiànyì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đề xuất”.',NULL,NULL,0,1,'',datetime('now')),
