INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk4-09','HSK4-09','HSK 4 · Đề 09','hsk','HSK 4',70,'published',1,'Đề luyện HSK 4 số 09 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk4-09-q01','seed-hsk4-09',1,'single_choice','Pinyin phù hợp với “支持” là phương án nào?','Pinyin của “支持” là “zhīchí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hỗ trợ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q02','seed-hsk4-09',2,'single_choice','Chọn từ Hán ngữ có nghĩa “quá trình”.','Từ phù hợp là “过程”, đọc là guòchéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q03','seed-hsk4-09',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实际 — shíjì”, nghĩa là “thực tế”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q04','seed-hsk4-09',4,'single_choice','Từ “态度” gần nghĩa nhất với phương án nào?','“态度” (tàidù) có nghĩa là “thái độ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q05','seed-hsk4-09',5,'single_choice','Pinyin phù hợp với “标准” là phương án nào?','Pinyin của “标准” là “biāozhǔn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tiêu chuẩn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q06','seed-hsk4-09',6,'single_choice','Chọn từ Hán ngữ có nghĩa “trách nhiệm”.','Từ phù hợp là “责任”, đọc là zérèn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q07','seed-hsk4-09',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “管理 — guǎnlǐ”, nghĩa là “quản lý”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q08','seed-hsk4-09',8,'single_choice','Từ “获得” gần nghĩa nhất với phương án nào?','“获得” (huòdé) có nghĩa là “đạt được”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q09','seed-hsk4-09',9,'single_choice','Pinyin phù hợp với “方法” là phương án nào?','Pinyin của “方法” là “fāngfǎ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phương pháp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q10','seed-hsk4-09',10,'single_choice','Chọn từ Hán ngữ có nghĩa “sắp xếp”.','Từ phù hợp là “安排”, đọc là ānpái. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q11','seed-hsk4-09',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “成功 — chénggōng”, nghĩa là “thành công”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q12','seed-hsk4-09',12,'single_choice','Từ “建议” gần nghĩa nhất với phương án nào?','“建议” (jiànyì) có nghĩa là “đề xuất”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
