('seed-hsk4-09-q41','seed-hsk4-09',41,'single_choice','Pinyin phù hợp với “支持” là phương án nào?','Pinyin của “支持” là “zhīchí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hỗ trợ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q42','seed-hsk4-09',42,'single_choice','Chọn từ Hán ngữ có nghĩa “quá trình”.','Từ phù hợp là “过程”, đọc là guòchéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q43','seed-hsk4-09',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实际 — shíjì”, nghĩa là “thực tế”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q44','seed-hsk4-09',44,'single_choice','Từ “态度” gần nghĩa nhất với phương án nào?','“态度” (tàidù) có nghĩa là “thái độ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q45','seed-hsk4-09',45,'single_choice','Pinyin phù hợp với “标准” là phương án nào?','Pinyin của “标准” là “biāozhǔn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tiêu chuẩn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q46','seed-hsk4-09',46,'single_choice','Chọn từ Hán ngữ có nghĩa “trách nhiệm”.','Từ phù hợp là “责任”, đọc là zérèn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q47','seed-hsk4-09',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “管理 — guǎnlǐ”, nghĩa là “quản lý”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q48','seed-hsk4-09',48,'single_choice','Từ “获得” gần nghĩa nhất với phương án nào?','“获得” (huòdé) có nghĩa là “đạt được”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q49','seed-hsk4-09',49,'single_choice','Pinyin phù hợp với “方法” là phương án nào?','Pinyin của “方法” là “fāngfǎ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phương pháp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-09-q50','seed-hsk4-09',50,'single_choice','Chọn từ Hán ngữ có nghĩa “sắp xếp”.','Từ phù hợp là “安排”, đọc là ānpái. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
