('seed-hsk4-10-q46','seed-hsk4-10',46,'single_choice','Chọn từ Hán ngữ có nghĩa “nội dung”.','Từ phù hợp là “内容”, đọc là nèiróng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-10-q47','seed-hsk4-10',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “能力 — nénglì”, nghĩa là “năng lực”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-10-q48','seed-hsk4-10',48,'single_choice','Từ “积极” gần nghĩa nhất với phương án nào?','“积极” (jījí) có nghĩa là “tích cực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-10-q49','seed-hsk4-10',49,'single_choice','Pinyin phù hợp với “失败” là phương án nào?','Pinyin của “失败” là “shībài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thất bại”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-10-q50','seed-hsk4-10',50,'single_choice','Chọn từ Hán ngữ có nghĩa “thích nghi”.','Từ phù hợp là “适应”, đọc là shìyìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
