('seed-hsk4-11-q20','seed-hsk4-11',20,'single_choice','Từ “失败” gần nghĩa nhất với phương án nào?','“失败” (shībài) có nghĩa là “thất bại”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
