INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk4-12','HSK4-12','HSK 4 · Đề 12','hsk','HSK 4',70,'published',1,'Đề luyện HSK 4 số 12 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk4-12-q01','seed-hsk4-12',1,'single_choice','Pinyin phù hợp với “获得” là phương án nào?','Pinyin của “获得” là “huòdé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đạt được”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q02','seed-hsk4-12',2,'single_choice','Chọn từ Hán ngữ có nghĩa “phương pháp”.','Từ phù hợp là “方法”, đọc là fāngfǎ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q03','seed-hsk4-12',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “安排 — ānpái”, nghĩa là “sắp xếp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q04','seed-hsk4-12',4,'single_choice','Từ “成功” gần nghĩa nhất với phương án nào?','“成功” (chénggōng) có nghĩa là “thành công”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q05','seed-hsk4-12',5,'single_choice','Pinyin phù hợp với “建议” là phương án nào?','Pinyin của “建议” là “jiànyì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đề xuất”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q06','seed-hsk4-12',6,'single_choice','Chọn từ Hán ngữ có nghĩa “giao lưu”.','Từ phù hợp là “交流”, đọc là jiāoliú. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q07','seed-hsk4-12',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “提供 — tígōng”, nghĩa là “cung cấp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q08','seed-hsk4-12',8,'single_choice','Từ “内容” gần nghĩa nhất với phương án nào?','“内容” (nèiróng) có nghĩa là “nội dung”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q09','seed-hsk4-12',9,'single_choice','Pinyin phù hợp với “能力” là phương án nào?','Pinyin của “能力” là “nénglì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “năng lực”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q10','seed-hsk4-12',10,'single_choice','Chọn từ Hán ngữ có nghĩa “tích cực”.','Từ phù hợp là “积极”, đọc là jījí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q11','seed-hsk4-12',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “失败 — shībài”, nghĩa là “thất bại”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q12','seed-hsk4-12',12,'single_choice','Từ “适应” gần nghĩa nhất với phương án nào?','“适应” (shìyìng) có nghĩa là “thích nghi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q13','seed-hsk4-12',13,'single_choice','Pinyin phù hợp với “发展” là phương án nào?','Pinyin của “发展” là “fāzhǎn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phát triển”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q14','seed-hsk4-12',14,'single_choice','Chọn từ Hán ngữ có nghĩa “hỗ trợ”.','Từ phù hợp là “支持”, đọc là zhīchí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q15','seed-hsk4-12',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “过程 — guòchéng”, nghĩa là “quá trình”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-12-q16','seed-hsk4-12',16,'single_choice','Từ “实际” gần nghĩa nhất với phương án nào?','“实际” (shíjì) có nghĩa là “thực tế”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
