INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk4-16','HSK4-16','HSK 4 · Đề 16','hsk','HSK 4',70,'published',1,'Đề luyện HSK 4 số 16 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk4-16-q01','seed-hsk4-16',1,'single_choice','Pinyin phù hợp với “态度” là phương án nào?','Pinyin của “态度” là “tàidù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thái độ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q02','seed-hsk4-16',2,'single_choice','Chọn từ Hán ngữ có nghĩa “tiêu chuẩn”.','Từ phù hợp là “标准”, đọc là biāozhǔn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q03','seed-hsk4-16',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “责任 — zérèn”, nghĩa là “trách nhiệm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q04','seed-hsk4-16',4,'single_choice','Từ “管理” gần nghĩa nhất với phương án nào?','“管理” (guǎnlǐ) có nghĩa là “quản lý”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q05','seed-hsk4-16',5,'single_choice','Pinyin phù hợp với “获得” là phương án nào?','Pinyin của “获得” là “huòdé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đạt được”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q06','seed-hsk4-16',6,'single_choice','Chọn từ Hán ngữ có nghĩa “phương pháp”.','Từ phù hợp là “方法”, đọc là fāngfǎ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q07','seed-hsk4-16',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “安排 — ānpái”, nghĩa là “sắp xếp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q08','seed-hsk4-16',8,'single_choice','Từ “成功” gần nghĩa nhất với phương án nào?','“成功” (chénggōng) có nghĩa là “thành công”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q09','seed-hsk4-16',9,'single_choice','Pinyin phù hợp với “建议” là phương án nào?','Pinyin của “建议” là “jiànyì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đề xuất”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-16-q10','seed-hsk4-16',10,'single_choice','Chọn từ Hán ngữ có nghĩa “giao lưu”.','Từ phù hợp là “交流”, đọc là jiāoliú. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
