('seed-hsk4-16-q22','seed-hsk4-16',22,'single_choice','Chọn từ Hán ngữ có nghĩa “tiêu chuẩn”.','Từ phù hợp là “标准”, đọc là biāozhǔn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
