INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk4-17','HSK4-17','HSK 4 · Đề 17','hsk','HSK 4',70,'published',1,'Đề luyện HSK 4 số 17 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk4-17-q01','seed-hsk4-17',1,'single_choice','Pinyin phù hợp với “交流” là phương án nào?','Pinyin của “交流” là “jiāoliú”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giao lưu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q02','seed-hsk4-17',2,'single_choice','Chọn từ Hán ngữ có nghĩa “cung cấp”.','Từ phù hợp là “提供”, đọc là tígōng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q03','seed-hsk4-17',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “内容 — nèiróng”, nghĩa là “nội dung”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q04','seed-hsk4-17',4,'single_choice','Từ “能力” gần nghĩa nhất với phương án nào?','“能力” (nénglì) có nghĩa là “năng lực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q05','seed-hsk4-17',5,'single_choice','Pinyin phù hợp với “积极” là phương án nào?','Pinyin của “积极” là “jījí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tích cực”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q06','seed-hsk4-17',6,'single_choice','Chọn từ Hán ngữ có nghĩa “thất bại”.','Từ phù hợp là “失败”, đọc là shībài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q07','seed-hsk4-17',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “适应 — shìyìng”, nghĩa là “thích nghi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q08','seed-hsk4-17',8,'single_choice','Từ “发展” gần nghĩa nhất với phương án nào?','“发展” (fāzhǎn) có nghĩa là “phát triển”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q09','seed-hsk4-17',9,'single_choice','Pinyin phù hợp với “支持” là phương án nào?','Pinyin của “支持” là “zhīchí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hỗ trợ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q10','seed-hsk4-17',10,'single_choice','Chọn từ Hán ngữ có nghĩa “quá trình”.','Từ phù hợp là “过程”, đọc là guòchéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
