('seed-hsk4-17-q26','seed-hsk4-17',26,'single_choice','Chọn từ Hán ngữ có nghĩa “thất bại”.','Từ phù hợp là “失败”, đọc là shībài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q27','seed-hsk4-17',27,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “适应 — shìyìng”, nghĩa là “thích nghi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q28','seed-hsk4-17',28,'single_choice','Từ “发展” gần nghĩa nhất với phương án nào?','“发展” (fāzhǎn) có nghĩa là “phát triển”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q29','seed-hsk4-17',29,'single_choice','Pinyin phù hợp với “支持” là phương án nào?','Pinyin của “支持” là “zhīchí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hỗ trợ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-17-q30','seed-hsk4-17',30,'single_choice','Chọn từ Hán ngữ có nghĩa “quá trình”.','Từ phù hợp là “过程”, đọc là guòchéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
