INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk4-18','HSK4-18','HSK 4 · Đề 18','hsk','HSK 4',70,'published',1,'Đề luyện HSK 4 số 18 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk4-18-q01','seed-hsk4-18',1,'single_choice','Pinyin phù hợp với “过程” là phương án nào?','Pinyin của “过程” là “guòchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quá trình”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q02','seed-hsk4-18',2,'single_choice','Chọn từ Hán ngữ có nghĩa “thực tế”.','Từ phù hợp là “实际”, đọc là shíjì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q03','seed-hsk4-18',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “态度 — tàidù”, nghĩa là “thái độ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q04','seed-hsk4-18',4,'single_choice','Từ “标准” gần nghĩa nhất với phương án nào?','“标准” (biāozhǔn) có nghĩa là “tiêu chuẩn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q05','seed-hsk4-18',5,'single_choice','Pinyin phù hợp với “责任” là phương án nào?','Pinyin của “责任” là “zérèn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trách nhiệm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q06','seed-hsk4-18',6,'single_choice','Chọn từ Hán ngữ có nghĩa “quản lý”.','Từ phù hợp là “管理”, đọc là guǎnlǐ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q07','seed-hsk4-18',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “获得 — huòdé”, nghĩa là “đạt được”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q08','seed-hsk4-18',8,'single_choice','Từ “方法” gần nghĩa nhất với phương án nào?','“方法” (fāngfǎ) có nghĩa là “phương pháp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q09','seed-hsk4-18',9,'single_choice','Pinyin phù hợp với “安排” là phương án nào?','Pinyin của “安排” là “ānpái”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sắp xếp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q10','seed-hsk4-18',10,'single_choice','Chọn từ Hán ngữ có nghĩa “thành công”.','Từ phù hợp là “成功”, đọc là chénggōng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
