('seed-hsk4-18-q31','seed-hsk4-18',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “建议 — jiànyì”, nghĩa là “đề xuất”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q32','seed-hsk4-18',32,'single_choice','Từ “交流” gần nghĩa nhất với phương án nào?','“交流” (jiāoliú) có nghĩa là “giao lưu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-18-q33','seed-hsk4-18',33,'single_choice','Pinyin phù hợp với “提供” là phương án nào?','Pinyin của “提供” là “tígōng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cung cấp”.',NULL,NULL,0,1,'',datetime('now')),
