('seed-hsk4-19-q36','seed-hsk4-19',36,'single_choice','Từ “责任” gần nghĩa nhất với phương án nào?','“责任” (zérèn) có nghĩa là “trách nhiệm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q37','seed-hsk4-19',37,'single_choice','Pinyin phù hợp với “管理” là phương án nào?','Pinyin của “管理” là “guǎnlǐ”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “quản lý”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q38','seed-hsk4-19',38,'single_choice','Chọn từ Hán ngữ có nghĩa “đạt được”.','Từ phù hợp là “获得”, đọc là huòdé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q39','seed-hsk4-19',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “方法 — fāngfǎ”, nghĩa là “phương pháp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q40','seed-hsk4-19',40,'single_choice','Từ “安排” gần nghĩa nhất với phương án nào?','“安排” (ānpái) có nghĩa là “sắp xếp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q41','seed-hsk4-19',41,'single_choice','Pinyin phù hợp với “成功” là phương án nào?','Pinyin của “成功” là “chénggōng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thành công”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q42','seed-hsk4-19',42,'single_choice','Chọn từ Hán ngữ có nghĩa “đề xuất”.','Từ phù hợp là “建议”, đọc là jiànyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q43','seed-hsk4-19',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “交流 — jiāoliú”, nghĩa là “giao lưu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q44','seed-hsk4-19',44,'single_choice','Từ “提供” gần nghĩa nhất với phương án nào?','“提供” (tígōng) có nghĩa là “cung cấp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-19-q45','seed-hsk4-19',45,'single_choice','Pinyin phù hợp với “内容” là phương án nào?','Pinyin của “内容” là “nèiróng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nội dung”.',NULL,NULL,0,1,'',datetime('now')),
