('seed-hsk4-20-q41','seed-hsk4-20',41,'single_choice','Pinyin phù hợp với “发展” là phương án nào?','Pinyin của “发展” là “fāzhǎn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phát triển”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q42','seed-hsk4-20',42,'single_choice','Chọn từ Hán ngữ có nghĩa “hỗ trợ”.','Từ phù hợp là “支持”, đọc là zhīchí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q43','seed-hsk4-20',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “过程 — guòchéng”, nghĩa là “quá trình”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q44','seed-hsk4-20',44,'single_choice','Từ “实际” gần nghĩa nhất với phương án nào?','“实际” (shíjì) có nghĩa là “thực tế”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q45','seed-hsk4-20',45,'single_choice','Pinyin phù hợp với “态度” là phương án nào?','Pinyin của “态度” là “tàidù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thái độ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q46','seed-hsk4-20',46,'single_choice','Chọn từ Hán ngữ có nghĩa “tiêu chuẩn”.','Từ phù hợp là “标准”, đọc là biāozhǔn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q47','seed-hsk4-20',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “责任 — zérèn”, nghĩa là “trách nhiệm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q48','seed-hsk4-20',48,'single_choice','Từ “管理” gần nghĩa nhất với phương án nào?','“管理” (guǎnlǐ) có nghĩa là “quản lý”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 4.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q49','seed-hsk4-20',49,'single_choice','Pinyin phù hợp với “获得” là phương án nào?','Pinyin của “获得” là “huòdé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đạt được”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk4-20-q50','seed-hsk4-20',50,'single_choice','Chọn từ Hán ngữ có nghĩa “phương pháp”.','Từ phù hợp là “方法”, đọc là fāngfǎ. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
